package config

import (
	"fmt"
	"strings"
)

const (
	// additional deprecation messages
	deprecatedMsgMemoryEnabled      = `Please use 'cache.backend' and 'cache.enabled' instead.`
	deprecatedMsgMemoryExpiration   = `Please use 'cache.ttl' instead.`
	deprecatedMsgDatabaseMigrations = `Migrations are now embedded within Flipt and are no longer required on disk.`
)

// deprecation represents a deprecated configuration option
type deprecation struct {
	// the deprecated option
	option string
	// the (optional) additionalMessage to display
	additionalMessage string
}

func (d deprecation) String() string {
	return strings.TrimSpace(fmt.Sprintf("%q is deprecated and will be removed in a future version. %s", d.option, d.additionalMessage))
}

package config

import (
	"encoding/json"
	"time"

	"github.com/spf13/viper"
)

// cheers up the unparam linter
var _ defaulter = (*CacheConfig)(nil)

// CacheConfig contains fields, which enable and configure
// Flipt's various caching mechanisms.
//
// Currently, flipt support in-memory and redis backed caching.
type CacheConfig struct {
	Enabled bool              `json:"enabled" mapstructure:"enabled"`
	TTL     time.Duration     `json:"ttl,omitempty" mapstructure:"ttl"`
	Backend CacheBackend      `json:"backend,omitempty" mapstructure:"backend"`
	Memory  MemoryCacheConfig `json:"memory,omitempty" mapstructure:"memory"`
	Redis   RedisCacheConfig  `json:"redis,omitempty" mapstructure:"redis"`
}

func (c *CacheConfig) setDefaults(v *viper.Viper) {
	v.SetDefault("cache", map[string]any{
		"enabled": false,
		"backend": CacheMemory,
		"ttl":     1 * time.Minute,
		"redis": map[string]any{
			"host":     "localhost",
			"port":     6379,
			"password": "",
			"db":       0,
		},

	Warnings []string
}

func Load(path string) (*Result, error) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	v.SetConfigFile(path)

	if err := v.ReadInConfig(); err != nil {
		return nil, fmt.Errorf("loading configuration: %w", err)
	}

	var (
		cfg         = &Config{}
		result      = &Result{Config: cfg}
		deprecators []deprecator
		defaulters  []defaulter
		validators  []validator
	)

	f := func(field any) {
		// for-each deprecator implementing field we collect
		// them up and return them to be run before unmarshalling and before setting defaults.
		if deprecator, ok := field.(deprecator); ok {
			deprecators = append(deprecators, deprecator)
		}

		// for-each defaulter implementing fields we invoke
		// setting any defaults during this prepare stage
		// on the supplied viper.
		if defaulter, ok := field.(defaulter); ok {
			defaulters = append(defaulters, defaulter)
		}

		// for-each validator implementing field we collect
		// them up and return them to be validated after
		// unmarshalling.
		if validator, ok := field.(validator); ok {
			validators = append(validators, validator)
		}
	}

	// invoke the field visitor on the root config firsts
	root := reflect.ValueOf(cfg).Interface()
	f(root)

	val := reflect.ValueOf(cfg).Elem()
	for i := 0; i < val.NumField(); i++ {
		// search for all expected env vars since Viper cannot
		// infer when doing Unmarshal + AutomaticEnv.
		// see: https://github.com/spf13/viper/issues/761
		var (
			structField = val.Type().Field(i)
			key         = fieldKey(structField)
		)

		bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)

	store = sqlite.NewStore(db, logger)
case sql.Postgres, sql.CockroachDB:
	store = postgres.NewStore(db, logger)
case sql.MySQL:
	store = mysql.NewStore(db, logger)
default:
	return nil, fmt.Errorf("unsupported driver: %s", driver)
}

logger.Debug("store enabled", zap.Stringer("driver", driver))

var tracingProvider = trace.NewNoopTracerProvider()

if cfg.Tracing.Jaeger.Enabled {
	logger.Debug("otel tracing enabled")

	exp, err := jaeger.New(jaeger.WithAgentEndpoint(
		jaeger.WithAgentHost(cfg.Tracing.Jaeger.Host),
		jaeger.WithAgentPort(strconv.FormatInt(int64(cfg.Tracing.Jaeger.Port), 10)),
	))
	if err != nil {
		return nil, err
	}

	tracingProvider = tracesdk.NewTracerProvider(
		tracesdk.WithBatcher(
			exp,
			tracesdk.WithBatchTimeout(1*time.Second),
		),
		tracesdk.WithResource(resource.NewWithAttributes(
			semconv.SchemaURL,
			semconv.ServiceNameKey.String("flipt"),
			semconv.ServiceVersionKey.String(info.Version),
		)),
		tracesdk.WithSampler(tracesdk.AlwaysSample()),
	)

	logger.Debug("otel tracing exporter configured", zap.String("type", "jaeger"))
}

package config

import "github.com/spf13/viper"

// cheers up the unparam linter
var _ defaulter = (*TracingConfig)(nil)

// JaegerTracingConfig contains fields, which configure specifically
// Jaeger span and tracing output destination.
type JaegerTracingConfig struct {
	Enabled bool   `json:"enabled,omitempty" mapstructure:"enabled"`
	Host    string `json:"host,omitempty" mapstructure:"host"`
	Port    int    `json:"port,omitempty" mapstructure:"port"`
}

// TracingConfig contains fields, which configure tracing telemetry
// output destinations.
type TracingConfig struct {
	Jaeger JaegerTracingConfig `json:"jaeger,omitempty" mapstructure:"jaeger"`
}

func (c *TracingConfig) setDefaults(v *viper.Viper) {
	v.SetDefault("tracing", map[string]any{
		"jaeger": map[string]any{
			"enabled": false,
			"host":    "localhost",
			"port":    6831,
		},
	})
}

}

func (c *CacheConfig) deprecations(v *viper.Viper) []deprecation {
	var deprecations []deprecation

	if v.InConfig("cache.memory.enabled") {
		deprecations = append(deprecations, deprecation{

			option:            "cache.memory.enabled",
			additionalMessage: deprecatedMsgMemoryEnabled,
		})
	}

	if v.InConfig("cache.memory.expiration") {
		deprecations = append(deprecations, deprecation{
			option:            "cache.memory.expiration",
			additionalMessage: deprecatedMsgMemoryExpiration,
		})
	}

	return deprecations
}

// CacheBackend is either memory or redis
type CacheBackend uint8

	#server: {
		protocol?:   "http" | "https" | *"http"
		host?:       string | *"0.0.0.0"
		https_port?: int | *443
		http_port?:  int | *8080
		grpc_port?:  int | *9000
		cert_file?:  string
		cert_key?:   string
	}

	#tracing: {
		// Jaeger
		jaeger?: {
			enabled?: bool | *false
			host?:    string | *"localhost"
			port?:    int | *6831
		}
	}

	#ui: enabled?: bool | *true
}

	HTTPPort:  8080,
	HTTPSPort: 443,
	GRPCPort:  9000,
},

Tracing: TracingConfig{
	Jaeger: JaegerTracingConfig{
		Enabled: false,
		Host:    jaeger.DefaultUDPSpanServerHost,
		Port:    jaeger.DefaultUDPSpanServerPort,
	},
},

Database: DatabaseConfig{
	URL:         "file:/var/opt/flipt/flipt.db",
	MaxIdleConn: 2,
},

Meta: MetaConfig{
	CheckForUpdates:  true,

